package export_ohrats_rc_session_management

import (
	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/identitystore"
	"wit_component/ohrats_rc_session_types"
)

func Issue(userId string, expiresAtMs uint64) witTypes.Result[ohrats_rc_session_types.IssuedSession, string] {
	session, err := identitystore.IssueSession(userId, expiresAtMs)
	if err != nil {
		return witTypes.Err[ohrats_rc_session_types.IssuedSession, string](err.Error())
	}
	return witTypes.Ok[ohrats_rc_session_types.IssuedSession, string](session)
}

func Revoke(cookieHeader string) witTypes.Result[bool, string] {
	revoked, err := identitystore.RevokeSession(cookieHeader)
	if err != nil {
		return witTypes.Err[bool, string](err.Error())
	}
	return witTypes.Ok[bool, string](revoked)
}
